#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

#define rep(i, n) for (int i = 0; i < (n); ++i)

int n;
int* comp;
vector<int>* befor;
int t[3][3] = {{0, 1, 2}, {2, 0, 1}, {1, 2, 0}};

int* can_do(const int* solved, int on)
{
    int* res1 = new int[n]();
    int* res2 = new int[n]();

    rep(i, n)
    {
        if (solved[i] == 1 || comp[i] != on)
            continue;

        bool possible = true;
        for (int dependency : befor[i])
        {
            if (solved[dependency] == 0 && comp[dependency] != on)
            {
                possible = false;
                break;
            }
        }

        if (possible)
            res1[i] = 1;
    }

    rep(i, n)
    {
        if (res1[i] == 0)
            continue;

        bool possible = true;
        for (int dependency : befor[i])
        {
            if (solved[dependency] == 0 &&
                comp[dependency] == on &&
                res1[dependency] == 0)
            {
                possible = false;
                break;
            }
        }

        if (possible)
            res2[i] = 1;
    }

    delete[] res1;
    return res2;
}

int do_best(const int* solved, int on)
{
    int solvedCount = 0;
    rep(i, n)
        solvedCount += solved[i];

    if (solvedCount == n)
        return 0;

    int minTime = 32000;

    rep(i, 3)
    {
        int* can = can_do(solved, i);

        int count = 0;
        rep(j, n)
            count += can[j];

        if (count == 0)
        {
            delete[] can;
            continue;
        }

        int* nextSolved = new int[n];
        rep(j, n)
            nextSolved[j] = solved[j] || can[j];

        int currentTime = do_best(nextSolved, i) + t[on][i] + count;
        minTime = min(minTime, currentTime);

        delete[] nextSolved;
        delete[] can;
    }

    return minTime;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    comp = new int[n];
    befor = new vector<int>[n];

    rep(i, n)
    {
        cin >> comp[i];
        --comp[i];
    }

    rep(i, n)
    {
        int k;
        cin >> k;

        rep(j, k)
        {
            int dependency;
            cin >> dependency;
            befor[i].push_back(dependency - 1);
        }
    }

    int* solved = new int[n]();
    int minTime = 32000;

    rep(i, 3)
    {
        int* can = can_do(solved, i);

        int count = 0;
        rep(j, n)
            count += can[j];

        if (count == 0)
        {
            delete[] can;
            continue;
        }

        int* nextSolved = new int[n];
        rep(j, n)
            nextSolved[j] = solved[j] || can[j];

        minTime = min(minTime, do_best(nextSolved, i) + count);

        delete[] nextSolved;
        delete[] can;
    }

    cout << minTime << '\n';

    delete[] solved;
    delete[] befor;
    delete[] comp;

    return 0;
}

