    {
        int *can = can_do(solved,i);
        int c = 0;
        rep(j,n) if (can[j] == 1) c++;
        if (c==0) continue;

        int *n_solved = new int[n];
        rep(j,n) n_solved[j] = 0;
        rep(j,n) if (solved[j] == 1 || can[j] == 1) n_solved[j] = 1;
        int tt = do_best(n_solved,i) + c;
        if (tt < min_t) min_t = tt;
        delete[] n_solved;
        delete[] can;
    }

    wl(min_t);
}
